class Rekenmachine:
    def optellen(self, a, b):
        return a + b
    def aftrekken(self, a, b):
        return a - b
    def vermenigvuldigen(self, a, b):
        return a * b
    def delen(self, a, b):
        if b == 0:
            return 'Fout: delen door nul'
        return a / b
```

```python
def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr
```

```python
def fibonacci(n):
    if n <= 1:
        return n
    a, b = 0, 1
    for _ in range(2, n+1):
        a, b = b, a + b
    return b
```

